        lhs.museumID == rhs.museumID && lhs.trackID == rhs.trackID
    }
    func hash(into hasher: inout Hasher) {
        hasher.combine(museumID)
        hasher.combine(trackID)
    }
}
let keys: Set<TourKey> = [
    TourKey(museumID: 1, trackID: 3),
    TourKey(museumID: 2, trackID: 3)
]
