    static func == (lhs: LanguageTag, rhs: LanguageTag) -> Bool {
        lhs.code.lowercased() == rhs.code.lowercased()
    }
    func hash(into hasher: inout Hasher) {
        hasher.combine(code.lowercased())
    }
}
let first = LanguageTag(code: "EN")
let second = LanguageTag(code: "en")
print(first == second)
print(first.hashValue == second.hashValue)
print(Set([first, second]).count)

Вывод true, true, 1. Та же нормализация применяется к равенству и хэшированию; пример ограничен ASCII, не задаёт общую политику Unicode.

